def expand_slots(spec: str) -> list[str]:
    """
    Expands a warehouse slot spec into an ordered list of slot names.

    Args:
        spec: A comma-separated string of slot tokens.

    Returns:
        A list of strings representing the expanded slot names.
    """
    stripped_spec = spec.strip()
    if not stripped_spec:
        return []

    raw_tokens = spec.split(',')
    tokens = []
    for t in raw_tokens:
        s = t.strip()
        if not s:
            raise ValueError("Empty token encountered in spec")
        tokens.append(s)

    def is_valid_slot(s: str) -> bool:
        # Must be one uppercase letter followed by a number from 1 to 99.
        # No leading zeros allowed (e.g., A07 is invalid, A1 is valid).
        if len(s) < 2 or not s[0].isupper():
            return False
        num_str = s[1:]
        if not num_str.isdigit() or num_str.startswith('0'):
            return False
        val = int(num_str)
        return 1 <= val <= 99

    def get_slots_from_token(t: str) -> list[str]:
        if '-' in t:
            parts = t.split('-')
            if len(parts) != 2:
                raise ValueError("Range must have exactly two parts separated by a hyphen.")
            s1, s2 = parts
            if not is_valid_slot(s1) or not is_valid_slot(s2):
                raise ValueError("Invalid slot name in range.")
            if s1[0] != s2[0]:
                raise ValueError("Range bounds must have the same letter.")

            v1 = int(s1[1:])
            v2 = int(s2[1:])
            letter = s1[0]
            if v1 <= v2:
                # Range in increasing order
                return [f"{letter}{i}" for i in range(v1, v2 + 1)]
            else:
                # Range in decreasing order
                return [f"{letter}{i}" for i in range(v1, v2 - 1, -1)]
        else:
            if not is_valid_slot(t):
                raise ValueError("Invalid slot name.")
            return [t]

    result = []
    for token in tokens:
        if token.startswith('!'):
            # Removal token
            inner = token[1:]
            if not inner:
                raise ValueError("Removal token cannot be empty.")
            slots_to_remove = get_slots_from_token(inner)
            for s in slots_to_remove:
                if s in result:
                    # Remove the first occurrence found. 
                    # Since addition logic ensures uniqueness, this removes the only occurrence.
                    result.remove(s)
        else:
            # Addition token
            slots_to_add = get_slots_from_token(token)
            for s in slots_to_add:
                # Only append if the slot is not already present in the list.
                if s not in result:
                    result.append(s)

    return result
