def kth_badge(length: int, k: int) -> str:
    """
    Returns the k-th lexicographically ordered badge of a given length.

    A badge is a string of letters A, B, C, D where:
    1. No two adjacent letters are equal.
    2. The substring 'AD' never occurs.
    """
    # dp[i][p] stores the number of valid suffixes of length i 
    # that can follow a character p (0=A, 1=B, 2=C, 3=D).
    dp = [[0] * 4 for _ in range(length + 1)]

    # Base case: an empty suffix (length 0) can be formed in 1 way.
    for p in range(4):
        dp[0][p] = 1

    # Fill the DP table
    # dp[i][p] = sum of dp[i-1][c] for all valid next characters c.
    for i in range(1, length + 1):
        for p in range(4):
            for c in range(4):
                # Condition 1: no adjacent letters equal (c != p)
                # Condition 2: "AD" is forbidden (p=0, c=3)
                if c != p and not (p == 0 and c == 3):
                    dp[i][p] += dp[i-1][c]

    # Calculate the total number of valid badges for the given length.
    # At position 0, any character c can be chosen as the first character.
    # The number of valid suffixes of length length-1 that can follow c
    # is given by dp[length-1][c].
    total = 0
    for c in range(4):
        total += dp[length - 1][c]

    # Standard error check for k
    if k < 1 or k > total:
        raise ValueError("k is out of bounds")

    res = []
    prev = -1

    # Iteratively determine each character of the k-th badge.
    for i in range(length):
        for c in range(4):
            if i == 0:
                # For the first character, any of A, B, C, D is possible.
                count = dp[length - 1][c]
                if k <= count:
                    res.append(chr(ord('A') + c))
                    prev = c
                    break
                else:
                    k -= count
            else:
                # For subsequent characters, satisfy the constraints relative to 'prev'.
                if c != prev and not (prev == 0 and c == 3):
                    # The remaining suffix length is (length - 1 - i).
                    count = dp[length - 1 - i][c]
                    if k <= count:
                        res.append(chr(ord('A') + c))
                        prev = c
                        break
                    else:
                        k -= count

    return "".join(res)

