def run_rover(grid: list[str], commands: str) -> tuple[int, int, str]:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting position and all portals
    start_pos = None
    portals = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif 'a' <= grid[r][c] <= 'z':
                if grid[r][c] not in portals:
                    portals[grid[r][c]] = []
                portals[grid[r][c]].append((r, c))

    # Rover's current state
    curr_r, curr_c = start_pos
    facing_dir = 0  # 0: N, 1: E, 2: S, 3: W
    d_vectors = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Parse and execute commands
    i = 0
    while i < len(commands):
        char = commands[i]
        if char not in "FBLR":
            raise ValueError("Invalid command character.")
        i += 1

        count_str = ""
        while i < len(commands) and commands[i].isdigit():
            count_str += commands[i]
            i += 1

        count = 1
        if count_str:
            if count_str == "0" or (len(count_str) > 1 and count_str[0] == "0"):
                raise ValueError("Invalid repeat count.")
            count = int(count_str)

        # Execute the command repeat times
        for _ in range(count):
            if char == 'L':
                facing_dir = (facing_dir - 1) % 4
            elif char == 'R':
                facing_dir = (facing_dir + 1) % 4
            elif char == 'F':
                move_dir = facing_dir
                dr, dc = d_vectors[move_dir]
                nr, nc = curr_r + dr, curr_c + dc
                # Check if the adjacent cell is within bounds and not a wall
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                    curr_r, curr_c = nr, nc
                    # Handle sliding on ice
                    while grid[curr_r][curr_c] == '~':
                        next_r, next_c = curr_r + dr, curr_c + dc
                        if 0 <= next_r < rows and 0 <= next_c < cols and grid[next_r][next_c] != '#':
                            curr_r, curr_c = next_r, next_c
                        else:
                            break
                    # Handle teleportation if rest position is a portal
                    if 'a' <= grid[curr_r][curr_c] <= 'z':
                        coords = portals[grid[curr_r][curr_c]]
                        curr_r, curr_c = coords[1] if (curr_r, curr_c) == coords[0] else coords[0]
            elif char == 'B':
                move_dir = (facing_dir + 2) % 4
                dr, dc = d_vectors[move_dir]
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                    curr_r, curr_c = nr, nc
                    # Handle sliding on ice
                    while grid[curr_r][curr_c] == '~':
                        next_r, next_c = curr_r + dr, curr_c + dc
                        if 0 <= next_r < rows and 0 <= next_c < cols and grid[next_r][next_c] != '#':
                            curr_r, curr_c = next_r, next_c
                        else:
                            break
                    # Handle teleportation if rest position is a portal
                    if 'a' <= grid[curr_r][curr_c] <= 'z':
                        coords = portals[grid[curr_r][curr_c]]
                        curr_r, curr_c = coords[1] if (curr_r, curr_c) == coords[0] else coords[0]

    # Final facing string
    facing_chars = ["N", "E", "S", "W"]
    return (curr_r, curr_c, facing_chars[facing_dir])
