from datetime import datetime, timedelta

def meeting_dates(year: int, weekday: int, n: int, closed: list[str]) -> list[str]:
    """
    Lists the dates of a monthly club meeting in the given year (Gregorian calendar).

    Args:
        year: The year of the meetings.
        weekday: 0 for Monday, 1 for Tuesday, ..., 6 for Sunday.
        n: Occurrence count (1..5 from start, -1..-5 from end).
        closed: List of strings "YYYY-MM-DD" where the clubhouse is closed.

    Returns:
        A list of "YYYY-MM-DD" strings for the meeting dates in chronological order.
    """
    # Validation of input parameters
    if not (0 <= weekday <= 6):
        raise ValueError("Weekday must be an integer between 0 and 6.")
    if n == 0 or abs(n) > 5:
        raise ValueError("n must be between -5 and 5, excluding 0.")

    meeting_dates_list = []

    # Iterate through each month of the year
    for month in range(1, 13):
        # Find all occurrences of the specified weekday in the current month
        weekday_dates = []
        for day_num in range(1, 32):
            try:
                d = datetime(year, month, day_num)
                if d.weekday() == weekday:
                    weekday_dates.append(d)
            except ValueError:
                # This handles months with fewer than 31 days
                break

        # Select the nominal meeting date based on n
        nominal_date = None
        if n > 0:
            if len(weekday_dates) >= n:
                nominal_date = weekday_dates[n - 1]
        else:
            abs_n = abs(n)
            if len(weekday_dates) >= abs_n:
                nominal_date = weekday_dates[len(weekday_dates) - abs_n]

        # If no such occurrence exists for the month, skip it
        if nominal_date is None:
            continue

        # Handle closed dates by moving to the next calendar day iteratively
        current_date = nominal_date
        while True:
            date_str = current_date.strftime("%Y-%m-%d")
            if date_str not in closed:
                # If the meeting day is found and it's still in the same month, record it
                if current_date.month == month:
                    meeting_dates_list.append(date_str)
                break
            else:
                # Move to the next day
                current_date += timedelta(days=1)
                # If the move takes us into the next month, the month has no meeting
                if current_date.month != month:
                    break

    return meeting_dates_list

