from datetime import date, timedelta

def shift_working_days(start: str, n: int, holidays: list[str], rest_days: list[int]) -> str:
    """
    Shifts a date by n working days.

    - n > 0: n-th working day strictly after start.
    - n < 0: |n|-th working day strictly before start.
    - n == 0: start itself if it is a working day, else the first working day after start.
    """
    # Check if rest_days includes all 7 days of the week
    rest_set = set(rest_days)
    if len(rest_set) == 7:
        raise ValueError("rest_days cannot contain all seven weekdays.")

    # Parse the input date string
    current_date = date.fromisoformat(start)

    def is_working_day(d: date) -> bool:
        # d.weekday() returns 0 for Monday, 1 for Tuesday, ..., 6 for Sunday
        if d.weekday() in rest_set:
            return False
        if d.isoformat() in holidays:
            return False
        return True

    if n == 0:
        # n == 0: start itself if it is a working day, otherwise the first working day after start.
        if is_working_day(current_date):
            return current_date.isoformat()
        else:
            # Find the first working day strictly after current_date
            check_date = current_date + timedelta(days=1)
            while not is_working_day(check_date):
                check_date += timedelta(days=1)
            return check_date.isoformat()

    elif n > 0:
        # n > 0: the n-th working day STRICTLY AFTER start.
        count = 0
        check_date = current_date + timedelta(days=1)
        while count < n:
            if is_working_day(check_date):
                count += 1
            if count < n:
                check_date += timedelta(days=1)
        return check_date.isoformat()

    else:
        # n < 0: the |n|-th working day STRICTLY BEFORE start.
        count = 0
        m = abs(n)
        check_date = current_date - timedelta(days=1)
        while count < m:
            if is_working_day(check_date):
                count += 1
            if count < m:
                check_date -= timedelta(days=1)
        return check_date.isoformat()

