def runoff_winner(ballots: list[list[str]]) -> tuple[str, list[str]]:
    """
    Runs a ranked-choice election and returns the winner and the order of elimination.
    """
    # Identify all candidates from the ballots.
    all_candidates = set()
    for ballot in ballots:
        for candidate in ballot:
            all_candidates.add(candidate)

    if not all_candidates:
        raise ValueError("No candidates are present on the ballots.")

    # Calculate the Round 1 votes.
    # Every ballot counts as one vote for the first candidate on it who has not been eliminated.
    # Since no candidates are eliminated in Round 1, this is the first candidate on each non-empty ballot.
    round1_votes = {candidate: 0 for candidate in all_candidates}
    for ballot in ballots:
        if ballot:
            round1_votes[ballot[0]] += 1

    current_candidates = set(all_candidates)
    eliminated = []

    while True:
        # Step 1: Every ballot counts as one vote for the first candidate on it who has not been eliminated.
        # A ballot on which every candidate has been eliminated (or which is empty) is "exhausted".
        current_votes = {candidate: 0 for candidate in current_candidates}
        non_exhausted_count = 0

        for ballot in ballots:
            for candidate in ballot:
                if candidate in current_candidates:
                    current_votes[candidate] += 1
                    non_exhausted_count += 1
                    break

        # Step 2: If some candidate has strictly more than half of the non-exhausted ballots, that candidate wins.
        winner = None
        for candidate in current_candidates:
            if current_votes[candidate] > non_exhausted_count / 2:
                winner = candidate
                break

        if winner:
            return (winner, eliminated)

        # Step 3: Otherwise, if only one candidate is left, that candidate wins.
        if len(current_candidates) == 1:
            # Convert set to list to get the single remaining element.
            winner = list(current_candidates)[0]
            return (winner, eliminated)

        # Step 4: Otherwise one candidate is eliminated.
        # Find the candidate(s) with the fewest votes in this round.
        min_votes_current = min(current_votes[candidate] for candidate in current_candidates)
        candidates_with_min_current = [
            candidate for candidate in current_candidates 
            if current_votes[candidate] == min_votes_current
        ]

        # Tie-breaker logic:
        # 1. Fewest votes in ROUND 1.
        # 2. Last alphabetically.
        if len(candidates_with_min_current) == 1:
            to_eliminate = candidates_with_min_current[0]
        else:
            min_votes_r1 = min(round1_votes[candidate] for candidate in candidates_with_min_current)
            candidates_with_min_r1 = [
                candidate for candidate in candidates_with_min_current 
                if round1_votes[candidate] == min_votes_r1
            ]

            if len(candidates_with_min_r1) == 1:
                to_eliminate = candidates_with_min_r1[0]
            else:
                # Alphabetically last means the maximum string value in Python.
                to_eliminate = max(candidates_with_min_r1)

        # Finalize elimination and continue to next round.
        eliminated.append(to_eliminate)
        current_candidates.remove(to_eliminate)

