def fill_template(template: str, values: dict) -> str:
    """
    Expands a small template language by scanning the template from left to right.
    """
    res = []
    i = 0
    n = len(template)

    while i < n:
        # Check for {{ which produces a literal {
        if template.startswith("{{", i):
            res.append("{")
            i += 2
        elif template[i] == "{":
            # Start of a field
            # Find the next '}' character
            end_idx = template.find("}", i + 1)
            if end_idx == -1:
                raise ValueError("Missing closing brace for field")

            content = template[i + 1 : end_idx]
            # The content of a field cannot contain a {
            if "{" in content:
                raise ValueError("Nested braces not allowed in field content")

            # Field content is split by |
            parts = content.split("|")
            name = parts[0]
            if not name:
                raise ValueError("Field name cannot be empty")

            filters = parts[1:]

            # Validate all filters (must be valid even if name is not in values)
            for f in filters:
                if f == "upper":
                    pass
                elif f == "lower":
                    pass
                elif f == "rev":
                    pass
                elif f.startswith("pad:"):
                    n_str = f[4:]
                    if not n_str.isdigit():
                        raise ValueError("Malformed pad filter")
                elif f.startswith("cut:"):
                    n_str = f[4:]
                    if not n_str.isdigit():
                        raise ValueError("Malformed cut filter")
                else:
                    # This covers unknown names, empty pieces, or arguments on arg-less filters
                    raise ValueError(f"Invalid filter or malformed argument: {f}")

            # Apply filters based on whether the name exists in the values dict
            if name in values:
                val = str(values[name])
                for f in filters:
                    if f == "upper":
                        val = val.upper()
                    elif f == "lower":
                        val = val.lower()
                    elif f == "rev":
                        val = val[::-1]
                    elif f.startswith("pad:"):
                        pad_n = int(f[4:])
                        val = val.ljust(pad_n, ".")
                    elif f.startswith("cut:"):
                        cut_n = int(f[4:])
                        val = val[:cut_n]
                res.append(val)
            else:
                # If name not in values, result is <NAME?>
                res.append(f"<{name}?>")

            # Move index past the closing brace
            i = end_idx + 1
        elif template.startswith("}}", i):
            # Outside a field, }} produces a literal }
            res.append("}")
            i += 2
        elif template[i] == "}":
            # A } not followed by another } outside a field is an error
            raise ValueError("Unexpected closing brace")
        else:
            # Every other character is copied unchanged
            res.append(template[i])
            i += 1

    return "".join(res)
